import SwiftUI
struct FamilyView:View {
    @EnvironmentObject var store:FamilyStore
    @State private var editing:FamilyEvent?
    var body:some View{List{if store.events.isEmpty{VStack(spacing:12){Image("state_v5_no_events").resizable().scaledToFit().frame(height:130);Text("Chưa có sự kiện gia đình").font(.headline);Text("Thêm ngày giỗ, sinh nhật hoặc kỷ niệm.").foregroundStyle(.secondary).font(.subheadline)}.frame(maxWidth:.infinity).listRowBackground(Color.clear)};ForEach(store.events){e in Button{editing=e}label:{HStack{AssetIcon(name:"icon_family");VStack(alignment:.leading){Text(e.title).font(.headline);Text("\(e.day)/\(e.month) \(e.lunar ? "âm lịch" : "dương lịch")\(e.leap && e.lunar ? " nhuận" : "")").font(.caption).foregroundStyle(.secondary);if let next=e.occurrences(after:SolarDate(Date())).first{Text("\(next.label) · còn \(next.jd-SolarDate(Date()).jd) ngày").foregroundStyle(red).font(.caption)}else{Text("Không có lần lặp trong phạm vi tìm kiếm").font(.caption)}};Spacer();Image(systemName:"chevron.right")}}.buttonStyle(.plain).swipeActions{Button(role:.destructive){store.remove(e)}label:{Label("Xóa",systemImage:"trash")}}};Section("Thông báo"){Button("Bật nhắc việc"){Task{await store.enable()}};Text(store.reminderStatus).font(.caption)}}.navigationTitle("Gia đình Việt").toolbar{Button{editing=FamilyEvent(title:"",day:1,month:1)}label:{Image(systemName:"plus")}}.sheet(item:$editing){e in NavigationStack{EventEditor(event:e){store.save($0)}}}}
}
struct EventEditor:View{@Environment(\.dismiss) private var dismiss;@State var event:FamilyEvent;let save:(FamilyEvent)->Void;var body:some View{Form{TextField("Tên sự kiện",text:$event.title);TextField("Ghi chú",text:$event.note,axis:.vertical);Toggle("Lặp theo âm lịch",isOn:$event.lunar);Stepper("Ngày: \(event.day)",value:$event.day,in:1...(event.lunar ? 30:31));Stepper("Tháng: \(event.month)",value:$event.month,in:1...12);if event.lunar{Toggle("Chỉ tháng nhuận",isOn:$event.leap)};Toggle("Dùng ngày cuối nếu tháng thiếu",isOn:$event.clamp);Picker("Nhắc trước",selection:$event.reminderDays){ForEach([0,1,3,7,15,30],id:\.self){Text("\($0) ngày").tag($0)}};Text("Tháng nhuận chỉ lặp vào năm có đúng tháng nhuận. Thông báo đặt theo giờ Việt Nam, 8:00 sáng.").font(.caption)}.navigationTitle("Sự kiện gia đình").toolbar{ToolbarItem(placement:.cancellationAction){Button("Hủy"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("Lưu"){if !event.lunar{event.leap=false};save(event);dismiss()}.disabled(event.title.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty || (!event.lunar && SolarDate(2024,event.month,event.day).date==nil) || (event.lunar && event.day>30))}}}}
